<xs:complexType name="UrunSayfalama"><xs:sequence><xs:element name="BaslangicIndex" type="xs:int"/><xs:element name="KayitSayisi" type="xs:int"/></xs:sequence></xs:complexType>
</xs:schema><xs:schema targetNamespace="urn:test" elementFormDefault="qualified"><xs:element name="SelectUrun"><xs:complexType><xs:sequence><xs:element name="UyeKodu" type="xs:string"/><xs:element name="f" type="d:UrunFiltre"/><xs:element name="s" type="d:UrunSayfalama"/></xs:sequence></xs:complexType></xs:element></xs:schema></wsdl:types>
<wsdl:message name="Input"><wsdl:part name="parameters" element="t:SelectUrun"/></wsdl:message><wsdl:portType name="IUrun"><wsdl:operation name="SelectUrun"><wsdl:input message="t:Input"/></wsdl:operation></wsdl:portType>
<wsdl:binding name="Binding"><soap:binding transport="http://schemas.xmlsoap.org/soap/http"/><wsdl:operation name="SelectUrun"><soap:operation soapAction="urn:test/IUrun/SelectUrun"/></wsdl:operation></wsdl:binding></wsdl:definitions>
""");
var contract=new TicimaxContract([docs],new Uri("https://store.example.com/Servis/UrunServis.svc"));
Dictionary<string,object?> values=new(StringComparer.OrdinalIgnoreCase){["UyeKodu"]="test<&secret",["$filter"]=new Dictionary<string,object?>{{"Aktif",-1},{"UrunKartiID",7}},["$paging"]=new Dictionary<string,object?>{{"BaslangicIndex",25},{"KayitSayisi",25}}};
var(body,action)=contract.Request("SelectUrun",values);Check(body.Name==XName.Get("SelectUrun","urn:test"),"wrapper namespace");Check(body.Elements().Select(x=>x.Name.LocalName).SequenceEqual(new[]{"UyeKodu","f","s"}),"member order");Check(body.Descendants(XName.Get("BaslangicIndex","urn:data")).Single().Value=="25","offset and data namespace");Check(body.ToString().Contains("test&lt;&amp;secret"),"XML escape");Check(!contract.FilterFields("SelectUrun").Contains("StokKodu"),"unsupported SKU identified");values["Unknown"]=1;Reject(()=>contract.Request("SelectUrun",values),"unknown wrapper must fail");values.Remove("Unknown");
var bad=XDocument.Parse(docs.ToString().Replace("urn:test/IUrun/SelectUrun","urn:test/IUrun/SaveUrun"));Reject(()=>new TicimaxContract([bad],contract.Address).Request("SelectUrun",values),"write action refused");
foreach(var url in new[]{"http://store.example.com","https://127.0.0.1","https://store.local","https://store.example.com/secret","https://user:pass@store.example.com","https://store.example.com:8443"})Check(TicimaxSoap.ValidBase(url)==null,"unsafe URL");foreach(var ip in new[]{"127.0.0.1","10.0.0.1","172.16.0.1","192.168.1.1","169.254.169.254","100.64.0.1","::1","fc00::1"})Check(!TicimaxSoap.PublicIp(IPAddress.Parse(ip)),"private IP");
try{TicimaxSoap.Parse(Encoding.UTF8.GetBytes("<!DOCTYPE x [<!ENTITY e SYSTEM 'file:///secret'>]><x>&e;</x>"));throw new Exception("DTD accepted");}catch(System.Xml.XmlException){}
var card=TicimaxAdapter.MapCard(XElement.Parse("<UrunKarti><ID>7</ID><UrunAdi>Test</UrunAdi><Varyasyonlar><Varyasyon><ID>2</ID><StokKodu>SKU</StokKodu><Barkod>8691000000001</Barkod><StokAdedi>1.5</StokAdedi><SatisFiyati>24.99</SatisFiyati><ParaBirimiID>8</ParaBirimiID><KdvDahil>false</KdvDahil></Varyasyon></Varyasyonlar></UrunKarti>"));Check(card.Variants[0] is{Quantity:1.5m,CurrencyId:"8",VatIncluded:false},"decimal stock currency VAT preserved");
var config=new ConfigurationBuilder().AddInMemoryCollection(new Dictionary<string,string?>{{"Marketplaces:Ticimax:production:BaseUrl","https://store.example.com"},{"Marketplaces:Ticimax:production:UyeKodu","test<&secret"}}).Build();var fake=new Fake(docs.ToString());var soapClient=new TicimaxSoap(fake,config);var adapter=new TicimaxAdapter(soapClient);var settings=new ConnectionSettings("test","ticimax","real","production");
await adapter.Cards(settings,new(Search:"7",Page:1),default);Check(fake.Posts==1&&fake.Last!.Contains("<BaslangicIndex xmlns=\"urn:data\">25</BaslangicIndex>"),"native page forwarded");try{await adapter.Cards(settings,new(Search:"SKU",SearchType:"SKU"),default);throw new Exception("unsupported search accepted");}catch(IntegrationException e){Check(e.Code=="unsupported_filter","unsupported filter error");}Check(fake.Posts==1,"no broad fetch after unsupported search");
try{await soapClient.Call(settings,"UrunServis","SaveUrun",new(),default);throw new Exception("write allowed");}catch(IntegrationException e){Check(e.Status==403,"write blocked");}Check(fake.Posts==1,"no write request");
Check(TicimaxAdapter.Validate(new(Page:-1))!=null&&TicimaxAdapter.Validate(new(Size:1000))!=null,"bounds");Console.WriteLine("PASS Ticimax contracts: WSDL namespace/order, escaping, native pagination, unsupported filters without broad fetch, decimal stock/currency/VAT, write refusal, private endpoints and DTD rejection. Fixture only; no live store call.");
class Fake(string wsdl):HttpMessageHandler,IHttpClientFactory{public int Posts;public string? Last;public HttpClient CreateClient(string name)=>new(this,false);protected override async Task<HttpResponseMessage> SendAsync(HttpRequestMessage r,CancellationToken ct){if(r.Method==HttpMethod.Get)return new(HttpStatusCode.OK){Content=new StringContent(wsdl)};Posts++;Last=await r.Content!.ReadAsStringAsync(ct);return new(HttpStatusCode.OK){Content=new StringContent("<s:Envelope xmlns:s='http://schemas.xmlsoap.org/soap/envelope/'><s:Body><SelectUrunResponse><SelectUrunResult/></SelectUrunResponse></s:Body></s:Envelope>")};}}
